mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("grid=ABCE,SFCS,ADEE word=ABCCED","true"),
        ("grid=A word=B","false"),
        ("grid=AB,CD word=ACD","true"),
        ("grid=AA word=AAA","false"),
        ("grid=ABC word=CBA","true"),
        ("  \ngrid=ABCE,SFCS,ADEE word=ABCCED\n  ","true"),
        ("\ngrid=ABC word=CBA\n","true")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS word-grid-search");
}
